'use strict';
const assert = require('assert');
const { escapeHtml } = require('./src/escape.js');

let failed = 0;
function check(name, fn) {
  try {
    fn();
    console.log('ok - ' + name);
  } catch (err) {
    failed += 1;
    console.log('FAIL - ' + name + ': ' + err.message);
  }
}

check('ampersand is escaped', () => {
  assert.strictEqual(escapeHtml('Fish & Chips'), 'Fish &amp; Chips');
});

check('angle brackets escape exactly once', () => {
  assert.strictEqual(escapeHtml('<b>'), '&lt;b&gt;');
});

check('double quotes escape', () => {
  assert.strictEqual(escapeHtml('say "hi"'), 'say &quot;hi&quot;');
});

check('mixed content escapes each character once', () => {
  assert.strictEqual(escapeHtml('a < b & c'), 'a &lt; b &amp; c');
});

if (failed > 0) {
  console.log(failed + ' check(s) failed');
  process.exit(1);
}
console.log('all checks passed');

