'use strict';

// Escapes text for inclusion in HTML/XML text nodes and attributes.
// Ampersand must be replaced first so it does not re-escape the
// entities produced by the later replacements.
function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

module.exports = { escapeHtml };
